import math

def sum_proper_divisors(n):
    n = abs(n)
    if n <= 1:
        return 0
    total = 1
    i = 2
    while i * i <= n:
        if n % i == 0:
            total += i
            if i != n // i:
                total += n // i
        i += 1
    return total


def are_equivalent(a, b):
    return sum_proper_divisors(a) == sum_proper_divisors(b)


